CREATE TABLE "user" (id text PRIMARY KEY,name text NOT NULL,email text UNIQUE NOT NULL,"emailVerified" boolean NOT NULL DEFAULT false,image text,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE session(id text PRIMARY KEY,"userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,token text UNIQUE NOT NULL,"expiresAt" timestamptz NOT NULL,"ipAddress" text,"userAgent" text,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE INDEX session_user_idx ON session("userId");
CREATE TABLE account(id text PRIMARY KEY,"userId" text NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,"accountId" text NOT NULL,"providerId" text NOT NULL,"accessToken" text,"refreshToken" text,"idToken" text,"accessTokenExpiresAt" timestamptz,"refreshTokenExpiresAt" timestamptz,scope text,password text,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now(),UNIQUE("providerId","accountId"));
CREATE TABLE verification(id text PRIMARY KEY,identifier text NOT NULL,value text NOT NULL,"expiresAt" timestamptz NOT NULL,"createdAt" timestamptz NOT NULL DEFAULT now(),"updatedAt" timestamptz NOT NULL DEFAULT now());
CREATE INDEX verification_identifier ON verification(identifier);
CREATE TABLE "rateLimit"(id text PRIMARY KEY,key text UNIQUE NOT NULL,count integer NOT NULL,"lastRequest" bigint NOT NULL);
CREATE TABLE workspaces(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE companies(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),name text NOT NULL DEFAULT 'Syntherisk',legal_name text,address text,registration_number text,tax_number text,base_currency text NOT NULL DEFAULT 'CAD' CHECK (base_currency ~ '^[A-Z]{3}$'),time_zone text NOT NULL DEFAULT 'America/Los_Angeles',tax_rate numeric(9,6) NOT NULL DEFAULT 0,version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,id));
CREATE TABLE brands(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),company_id uuid NOT NULL,name text NOT NULL DEFAULT 'Syntherisk',logo_url text NOT NULL DEFAULT '/brand/logo-primary.svg',FOREIGN KEY(workspace_id,company_id) REFERENCES companies(workspace_id,id));
CREATE TABLE memberships(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),user_id text NOT NULL REFERENCES "user"(id),roles text[] NOT NULL DEFAULT ARRAY['member'],status text NOT NULL DEFAULT 'active' CHECK(status IN('active','disabled')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,user_id),CHECK(roles <@ ARRAY['admin','operations','finance','reviewer','member','external']::text[]),CHECK(cardinality(roles)>0));
CREATE TABLE roles(code text PRIMARY KEY,label text NOT NULL);
INSERT INTO roles VALUES('admin','Administrator'),('operations','Operations'),('finance','Finance'),('reviewer','Reviewer'),('member','Member'),('external','External');
CREATE TABLE permissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),role_code text NOT NULL REFERENCES roles(code),resource text NOT NULL,operation text NOT NULL,scope text NOT NULL CHECK(scope IN('all','own','assigned','granted','none')),UNIQUE(workspace_id,role_code,resource,operation));
CREATE TABLE invitations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),email text NOT NULL,roles text[] NOT NULL,token_hash text UNIQUE NOT NULL,created_by text NOT NULL REFERENCES "user"(id),expires_at timestamptz NOT NULL,accepted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_log(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid REFERENCES workspaces(id),actor_id text,resource text NOT NULL,record_id text,action text NOT NULL,before_data jsonb,after_data jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_log_record ON audit_log(workspace_id,resource,record_id,created_at DESC);
CREATE TABLE user_preferences(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),user_id text NOT NULL REFERENCES "user"(id),settings jsonb NOT NULL DEFAULT '{}',version integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,user_id));
CREATE TABLE workspace_defaults(workspace_id uuid PRIMARY KEY REFERENCES workspaces(id),settings jsonb NOT NULL DEFAULT '{}',updated_by text NOT NULL REFERENCES "user"(id),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE theme_presets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),user_id text NOT NULL REFERENCES "user"(id),name text NOT NULL,tokens jsonb NOT NULL,is_default boolean NOT NULL DEFAULT false,UNIQUE(workspace_id,user_id,name));
CREATE TABLE layout_presets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),user_id text NOT NULL REFERENCES "user"(id),name text NOT NULL,layout jsonb NOT NULL,is_default boolean NOT NULL DEFAULT false,UNIQUE(workspace_id,user_id,name));
CREATE TABLE saved_views(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),user_id text NOT NULL REFERENCES "user"(id),resource text NOT NULL,name text NOT NULL,config jsonb NOT NULL,UNIQUE(workspace_id,user_id,resource,name));
CREATE TABLE attachments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),company_id uuid NOT NULL,resource text NOT NULL,record_id uuid NOT NULL,filename text NOT NULL,mime_type text NOT NULL,byte_size bigint NOT NULL CHECK(byte_size>=0),sha256 text NOT NULL,storage_key text UNIQUE NOT NULL,created_by text NOT NULL REFERENCES "user"(id),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(workspace_id,company_id) REFERENCES companies(workspace_id,id));
CREATE INDEX attachments_record ON attachments(workspace_id,resource,record_id);
CREATE TABLE import_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),user_id text NOT NULL REFERENCES "user"(id),resource text NOT NULL,status text NOT NULL CHECK(status IN('preview','completed','failed')),row_count integer NOT NULL DEFAULT 0,errors jsonb NOT NULL DEFAULT '[]',payload jsonb NOT NULL DEFAULT '[]',result jsonb,created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
CREATE TABLE export_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES workspaces(id),user_id text NOT NULL REFERENCES "user"(id),resource text NOT NULL,row_count integer NOT NULL,filters jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
